import { calculateShoppingTotal } from './utils/recurrence.js';
import { isSupabaseConfigured, supabase } from './services/supabase.js';
import { signIn, signUp, signOut, getSession } from './services/auth.js';
import { getMyMembership, createFamily, joinFamily, updateMyProfile, createFamilyInvite, removeFamilyMember } from './services/family.js';
import { subscribeToFamily } from './services/sync.js';
