async function runGlobalSearch(){
 const query=await openModal({title:'Поиск по семье',submitLabel:'Найти',content:'<label class="field"><span>Задачи, покупки, события и заметки</span><input name="query" required maxlength="120" placeholder="Введите слово или фразу"></label>',onSubmit:d=>requiredText(d.get('query'),'Поисковый запрос',120)});
 if(!query)return;
 try{
  const [tasks,shopping,events,notes]=await Promise.all([listTasks(state.membership.family_id),listShopping(state.membership.family_id),listCalendar(state.membership.family_id,'2000-01-01T00:00:00.000Z','2100-01-01T00:00:00.000Z'),listFamilyNotes(state.membership.family_id)]);
  const q=query.toLocaleLowerCase('ru-RU'); const matches=[];
  for(const x of tasks)if([x.title,x.description,x.category_name,x.creator_name].some(v=>String(v||'').toLocaleLowerCase('ru-RU').includes(q)))matches.push({type:'task',id:x.id,title:x.title,meta:`Задача · ${x.category_name}`});
  for(const x of shopping)if([x.title,x.category,x.store,x.note].some(v=>String(v||'').toLocaleLowerCase('ru-RU').includes(q)))matches.push({type:'shopping',id:x.id,title:x.title,meta:`Покупка · ${x.category}`});
  for(const x of events)if([x.title,x.description,x.event_type].some(v=>String(v||'').toLocaleLowerCase('ru-RU').includes(q)))matches.push({type:'event',id:x.id,title:x.title,meta:`Событие · ${formatDate(new Date(x.starts_at),{day:'numeric',month:'short'})}`});
  for(const x of notes)if([x.title,x.body].some(v=>String(v||'').toLocaleLowerCase('ru-RU').includes(q)))matches.push({type:'note',id:x.id,title:x.title||'Заметка',meta:'Семейная заметка'});
  const resultPromise=openModal({title:`Результаты: ${matches.length}`,submitLabel:'Закрыть',content:matches.length?`<div class="global-search-results">${matches.slice(0,40).map(x=>`<button type="button" class="global-search-result" data-global-target="${x.type}/${x.id}"><strong>${escapeHtml(x.title)}</strong><span class="muted">${escapeHtml(x.meta)}</span></button>`).join('')}</div>`:'<div class="empty-activity"><h3>Ничего не найдено</h3><p>Попробуйте другой запрос.</p></div>',onSubmit:()=>true});
  document.querySelectorAll('[data-global-target]').forEach(b=>b.addEventListener('click',()=>{const [type,id]=b.dataset.globalTarget.split('/');if(type==='note'){state.notes=null;location.hash='/family';}else{state.discussionContext=location.hash||'#/home';state.discussionScrollY=window.scrollY;state.discussion=null;location.hash=`/discussion/${type}/${id}`;}document.querySelector('.modal-sheet button[aria-label="Закрыть"]')?.click();}));
  await resultPromise;
 }catch(e){toast(friendlyError(e),'error');}
}
async function openNoteEditor(note=null){const result=await openModal({title:note?'Изменить заметку':'Семейная заметка',submitLabel:note?'Сохранить':'Добавить',content:`<label class="field"><span>Заголовок</span><input name="title" maxlength="120" value="${escapeAttr(note?.title||'')}" placeholder="Например, Важные контакты"></label><label class="field"><span>Текст</span><textarea name="body" rows="6" maxlength="10000" required>${escapeHtml(note?.body||'')}</textarea></label>`,onSubmit:d=>saveFamilyNote({familyId:state.membership.family_id,userId:state.session.user.id,note:{id:note?.id,title:String(d.get('title')||''),body:requiredText(d.get('body'),'Текст',10000)}})});if(result){state.notes=null;await loadRouteData('family');toast(note?'Заметка сохранена':'Заметка добавлена','success');}}
function clearPrivateState(){state.unsubscribe?.();state.unsubscribe=null;state.session=null;state.membership=null;state.profile=null;state.tasks=null;state.categories=null;state.members=null;state.shopping=null;state.archivedShopping=null;state.events=null;state.activity=null;state.notifications=null;state.notes=null;state.templates=null;state.stats=null;state.discussion=null;state.dashboardLoaded=false;state.error='';state.search='';state.commentReplyParent=null;}
async function confirmAction(title,description){return Boolean(await openModal({title,submitLabel:'Подтвердить',content:`<p class="muted">${escapeHtml(description)}</p>`,onSubmit:()=>true}));}
async function openTaskEditor(task=null){if(!state.categories)state.categories=await listCategories(state.membership.family_id);if(!state.members)state.members=await listMembers(state.membership.family_id);const cats=state.categories.map(c=>`<option value="${escapeAttr(c.name)}" ${c.name===(task?.category_name||'Другое')?'selected':''}>${escapeHtml(c.name)}</option>`).join('');const members=state.members.map(m=>`<option value="${m.user_id}" ${m.user_id===task?.assignee_id?'selected':''}>${escapeHtml(m.display_name)}</option>`).join('');const modalPromise=openModal({title:task?'Редактировать задачу':'Новая задача',submitLabel:task?'Сохранить':'Создать задачу',content:`<label class="field"><span>Название</span><input name="title" required maxlength="160" value="${escapeAttr(task?.title||'')}" placeholder="Что нужно сделать?"></label><label class="field"><span>Описание</span><textarea name="description" rows="3" maxlength="3000">${escapeHtml(task?.description||'')}</textarea></label><label class="field"><span>Категория</span><select name="category">${cats}</select></label><label class="field"><span>Исполнитель</span><select name="assignee"><option value="">Любой участник семьи</option>${members}</select></label><label class="field"><span>Срок</span><input name="due" type="datetime-local" value="${task?.due_at?escapeAttr(new Date(new Date(task.due_at).getTime()-new Date(task.due_at).getTimezoneOffset()*60000).toISOString().slice(0,16)):''}"></label><label class="field"><span>Приоритет</span><select name="priority">${PRIORITIES.map(p=>`<option value="${p.value}" ${p.value===(task?.priority||'normal')?'selected':''}>${p.label}</option>`).join('')}</select></label><label class="field"><span>Повторение</span><select name="recurrence"><option value="none" ${(task?.recurrence?.type||'none')==='none'?'selected':''}>Без повторения</option><option value="daily" ${task?.recurrence?.type==='daily'?'selected':''}>Ежедневно</option><option value="weekly" ${task?.recurrence?.type==='weekly'?'selected':''}>Еженедельно</option><option value="weekdays" ${task?.recurrence?.type==='weekdays'?'selected':''}>По дням недели</option><option value="monthly" ${task?.recurrence?.type==='monthly'?'selected':''}>Ежемесячно</option></select></label><div data-weekday-fields ${task?.recurrence?.type==='weekdays'?'':'hidden'}><span class="field-label">Повторять в дни</span><div class="weekday-checks">${[['1','Пн'],['2','Вт'],['3','Ср'],['4','Чт'],['5','Пт'],['6','Сб'],['0','Вс']].map(([v,l])=>`<label><input type="checkbox" name="weekdays" value="${v}" ${(task?.recurrence?.days||[]).includes(Number(v))?'checked':''}> ${l}</label>`).join('')}</div></div>`,onSubmit:async d=>{const payload={id:task?.id,version:task?.version,title:requiredText(d.get('title'),'Название',160),description:String(d.get('description')||''),category:d.get('category'),assigneeId:d.get('assignee'),dueAt:d.get('due')?new Date(d.get('due')).toISOString():null,priority:d.get('priority'),recurrence:{type:d.get('recurrence'),days:d.getAll('weekdays').map(Number)}};return saveTask({familyId:state.membership.family_id,userId:state.session.user.id,creatorName:task?.creator_name||state.membership.display_name,task:payload});}});const repeatSelect=document.querySelector('.modal-sheet select[name="recurrence"]');const weekdayFields=document.querySelector('.modal-sheet [data-weekday-fields]');const syncWeekdays=()=>{if(weekdayFields)weekdayFields.hidden=repeatSelect?.value!=='weekdays';};repeatSelect?.addEventListener('change',syncWeekdays);syncWeekdays();const result=await modalPromise;if(result){state.tasks=null;state.dashboardLoaded=false;state.activity=null;render();toast(task?'Задача сохранена':'Задача добавлена','success');}}
async function openShoppingEditor(item=null){const result=await openModal({title:item?'Редактировать товар':'Добавить товар',submitLabel:item?'Сохранить':'Добавить',content:`<label class="field"><span>Название товара</span><input name="title" required maxlength="160" value="${escapeAttr(item?.title||'')}" placeholder="Например, молоко"></label><div class="form-grid"><label class="field"><span>Количество</span><input name="quantity" type="number" min="0.01" step="0.01" required value="${item?.quantity||1}"></label><label class="field"><span>Единица</span><select name="unit">${['шт.','уп.','кг','г','л','мл','пач.','бут.'].map(u=>`<option ${u===(item?.unit||'шт.')?'selected':''}>${u}</option>`).join('')}</select></label></div><label class="field"><span>Категория</span><select name="category">${SHOPPING_CATEGORIES.map(c=>`<option ${c===(item?.category||'Другое')?'selected':''}>${c}</option>`).join('')}</select></label><label class="field"><span>Примерная цена за единицу (€)</span><input name="price" type="number" min="0" step="0.01" value="${item?.estimated_price??''}"></label><label class="field"><span>Магазин</span><input name="store" maxlength="100" value="${escapeAttr(item?.store||'')}"></label><label class="field"><span>Комментарий</span><textarea name="note" rows="2" maxlength="1000">${escapeHtml(item?.note||'')}</textarea></label>`,onSubmit:d=>saveShopping({familyId:state.membership.family_id,userId:state.session.user.id,creatorName:item?.creator_name||state.membership.display_name,item:{id:item?.id,version:item?.version,title:requiredText(d.get('title'),'Название',160),quantity:d.get('quantity'),unit:d.get('unit'),category:d.get('category'),price:d.get('price'),store:d.get('store'),note:d.get('note')}})});if(result){state.shopping=null;state.dashboardLoaded=false;state.activity=null;render();toast(item?'Товар обновлён':'Товар добавлен','success');}}
async function openEventEditor(){const modalPromise=openModal({title:'Семейное событие',submitLabel:'Сохранить',content:`<label class="field"><span>Название</span><input name="title" required maxlength="160" placeholder="Например, день рождения"></label><label class="field"><span>Тип</span><select name="type"><option value="birthday">День рождения</option><option value="meeting">Встреча</option><option value="chore">Поручение</option><option value="bill">Оплата счёта</option><option value="family">Семейное событие</option><option value="other">Другое</option></select></label><label class="field"><span>Дата и время</span><input name="starts" type="datetime-local" required></label><label class="field"><span>Описание</span><textarea name="description" rows="3" maxlength="2000"></textarea></label><label class="field"><span>Повторение</span><select name="recurrence"><option value="none">Без повторения</option><option value="daily">Ежедневно</option><option value="weekly">Еженедельно</option><option value="weekdays">По дням недели</option><option value="monthly">Ежемесячно</option></select></label><div data-event-weekdays hidden><span class="field-label">Повторять в дни</span><div class="weekday-checks">${[['1','Пн'],['2','Вт'],['3','Ср'],['4','Чт'],['5','Пт'],['6','Сб'],['0','Вс']].map(([v,l])=>`<label><input type="checkbox" name="eventWeekdays" value="${v}"> ${l}</label>`).join('')}</div></div>`,onSubmit:d=>{if(!d.get('starts'))throw new Error('Укажите дату события.');return saveCalendar({familyId:state.membership.family_id,userId:state.session.user.id,creatorName:state.membership.display_name,event:{title:requiredText(d.get('title'),'Название',160),type:d.get('type'),startsAt:new Date(d.get('starts')).toISOString(),description:d.get('description'),recurrence:{type:d.get('recurrence'),days:d.getAll('eventWeekdays').map(Number)}}});}});const eventRepeat=document.querySelector('.modal-sheet select[name="recurrence"]');const eventWeekdays=document.querySelector('.modal-sheet [data-event-weekdays]');const syncEventWeekdays=()=>{if(eventWeekdays)eventWeekdays.hidden=eventRepeat?.value!=='weekdays';};eventRepeat?.addEventListener('change',syncEventWeekdays);syncEventWeekdays();const result=await modalPromise;if(result){state.events=null;state.activity=null;render();toast('Событие сохранено','success');}}
function friendlyError(error) { const message = error?.message || 'Неизвестная ошибка'; if (/Invalid login credentials/i.test(message)) return 'Неверная почта или пароль.'; if (/Email not confirmed/i.test(message)) return 'Подтвердите адрес электронной почты по ссылке из письма.'; if (/User already registered/i.test(message)) return 'Этот адрес уже зарегистрирован. Попробуйте войти.'; return message; }
function initials(name) { return String(name || 'FH').trim().split(/\s+/).slice(0, 2).map(part => part[0] || '').join('').toUpperCase(); }
function safeColor(color) { return /^#[0-9a-f]{6}$/i.test(color || '') ? color : '#777D61'; }
function escapeHtml(value) { return String(value ?? '').replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch])); }
function escapeAttr(value) { return escapeHtml(value); }
